var o=`0420-frikadeller`;var i=`world-0420`;var t=`DK`;var r=`northern-europe`;var a=4;var l=32;var s={en:`Frikadeller`,ua:`Фрикадельки по-данськи`};var d={en:`A traditional dish from Denmark, centered on ground pork, ground veal, yellow onion, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Данія. Основні складники: свинячий фарш, телячий фарш, жовта цибуля, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-pork`,480,`g`],[`ground-veal`,200,`g`],[`yellow-onion`,170,`g`],[`chicken-egg`,1,`pcs`],[`whole-cow-milk`,130,`ml`],[`breadcrumbs`,90,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 19 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 19 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:19,i:[[`unsalted-butter`,75,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,12,`g`]]}];var u={slug:o,id:i,country:`DK`,region:r,servings:4,minutes:32,title:s,text:d,steps:g};export{t as country,u as default,i as id,l as minutes,r as region,a as servings,o as slug,g as steps,d as text,s as title};